ddl:
  CREATE OR REPLACE EDITIONABLE PACKAGE "W4O_<run_id>"."PKG_SRC_<run_id>" AS
  FUNCTION TWICE(P_ID NUMBER) RETURN NUMBER; -- w4src:package
END;
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "W4O_<run_id>"."PKG_SRC_<run_id>" AS
  FUNCTION TWICE(P_ID NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN P_ID * 2; -- w4src:package_body
  END;
END;
